// QNX 8.0: High-performance POSIX timer with Pulse
#include <sys/netmgr.h>
#include <sys/neutrino.h>
#include <time.h>

struct sigevent event;
SIGEV_PULSE_INIT(&event, coid, priority, CODE_TIMER, 0);
